import networkx as nx
from itertools import combinations

def girth(G):
    try:
        return nx.girth(G)
    except:
        pass
    best = float('inf')
    for v in G.nodes():
        # BFS
        dist = {v:0}
        parent = {v:None}
        from collections import deque
        q = deque([v])
        while q:
            x = q.popleft()
            for y in G.neighbors(x):
                if y not in dist:
                    dist[y] = dist[x]+1
                    parent[y] = x
                    q.append(y)
                elif parent[x] != y:
                    c = dist[x]+dist[y]+1
                    if c < best: best = c
    return best

# Try to build a graph on 11 vertices with girth >=6, trying many edges greedy
import random
random.seed(1)
best_edges = None
for trial in range(2000):
    verts = list(range(11))
    edges_candidates = list(combinations(verts,2))
    random.shuffle(edges_candidates)
    G = nx.Graph()
    G.add_nodes_from(verts)
    for (u,v) in edges_candidates:
        G.add_edge(u,v)
        g = girth(G)
        if g < 6:
            G.remove_edge(u,v)
    if best_edges is None or G.number_of_edges() > len(best_edges):
        best_edges = list(G.edges())

